CREATE TABLE public.gateway_activity_hour (
    subject text NOT NULL,
    device_id text DEFAULT ''::text NOT NULL,
    hour_start bigint NOT NULL,
    samples_ok integer DEFAULT 0 NOT NULL,
    samples_down integer DEFAULT 0 NOT NULL,
    samples_stopped integer DEFAULT 0 NOT NULL,
    online_seconds integer DEFAULT 0 NOT NULL,
    observations integer DEFAULT 0 NOT NULL,
    first_data_ts bigint,
    last_data_ts bigint,
    power_on integer DEFAULT 0 NOT NULL,
    power_off integer DEFAULT 0 NOT NULL,
    complete boolean DEFAULT false NOT NULL,
    checksum text DEFAULT ''::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    delivered_version integer DEFAULT 0 NOT NULL,
    CONSTRAINT gateway_activity_hour_subject_check CHECK ((subject = ANY (ARRAY['gateway'::text, 'device'::text])))
);


